@orders_bp.route("/bulk", methods=["POST"])
@require_role("manager")
def bulk_create_orders():
    items = request.get_json(silent=True) or []
    session = get_session()
    values = ", ".join(
        "({0}, '{1}', {2})".format(
            item.get("user_id", 0), item.get("status", "pending"), item.get("total", 0.0)
        )
        for item in items
    )
    if values:
        session.execute(text("INSERT INTO orders (user_id, status, total) VALUES " + values))
        session.commit()
    return jsonify({"imported": len(items)}), 201

@orders_bp.route("", methods=["POST"])
@require_auth
def create_order():
    payload = request.get_json(silent=True) or {}
    session = get_session()
    order = Order(
        user_id=g.current_user.id,
        status="pending",
        total=float(payload.get("total", 0.0)),
        shipping_address=payload.get("shipping_address", ""),
    )
    session.add(order)
    session.commit()
    return jsonify(order.to_dict()), 201

def require_role(minimum_role: str):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)
        return wrapper
    return decorator
